const (
	InitFlagFilename = "init"
)

type ProjectInitFlag struct {
	Initialized bool `json:"initialized"`
}

// InitOption is a functional option for Init.
type InitOption func(*initOptions)

type initOptions struct {
	profile string
}

// WithProfile sets the agent profile for the config.
func WithProfile(profile string) InitOption {
	return func(opts *initOptions) {
		opts.profile = profile
	}
}

// TODO: we need to remove the global config instance keeping it now just until everything is migrated
var instance atomic.Pointer[Config]

func Init(workingDir, dataDir string, debug bool, opts ...InitOption) (*Config, error) {
	options := &initOptions{
		profile: "crush", // default profile
	}
	for _, opt := range opts {
		opt(options)
	}

	cfg, err := Load(workingDir, dataDir, debug)
	if err != nil {
		return nil, err
	}
	// Store the profile in config
	cfg.Profile = options.profile
	instance.Store(cfg)
	return instance.Load(), nil
}

